using System.Collections.Concurrent;

namespace Meziantou.Framework.WebPlatform.Scripting;

/// <summary>The bindings of the interfaces implemented by the library. The tables are generated by SpecGen.</summary>
internal static partial class WebIdlBindings<TAdapter, TValue>
    where TAdapter : struct, IJsAdapter<TValue>
    where TValue : class
{
    // Written by LinkParents while the Interfaces field is initialized, so it must not have an initializer (the order of the
    // initializers of the partial declarations is not specified)
    private static Dictionary<Type, InterfaceBinding<TAdapter, TValue>>? s_byClrType;
    private static readonly ConcurrentDictionary<Type, InterfaceBinding<TAdapter, TValue>?> BindingCache = new();

    /// <summary>Gets the most derived interface implemented by an instance of <paramref name="type"/>.</summary>
    public static InterfaceBinding<TAdapter, TValue>? GetInterface(Type type)
    {
        if (BindingCache.TryGetValue(type, out var result))
            return result;

        var byClrType = s_byClrType ?? Link(Interfaces);
        for (var current = type; current is not null; current = current.BaseType)
        {
            if (byClrType.TryGetValue(current, out result))
                break;
        }

        BindingCache.TryAdd(type, result);
        return result;
    }

    /// <summary>Gets the legacy platform object behavior (https://webidl.spec.whatwg.org/#dfn-legacy-platform-object) of an interface or of its inherited interfaces.</summary>
    public static LegacyPlatformObjectBinding<TAdapter, TValue>? GetLegacyPlatformObject(InterfaceBinding<TAdapter, TValue> binding)
    {
        for (var current = binding; current is not null; current = current.Parent)
        {
            if (current.LegacyPlatformObject is { } legacy)
                return legacy;
        }

        return null;
    }

    private static void LinkParents(Dictionary<string, InterfaceBinding<TAdapter, TValue>> interfaces) => Link(interfaces);

    private static Dictionary<Type, InterfaceBinding<TAdapter, TValue>> Link(Dictionary<string, InterfaceBinding<TAdapter, TValue>> interfaces)
    {
        var byClrType = new Dictionary<Type, InterfaceBinding<TAdapter, TValue>>();

        // The interfaces of the WebAssembly namespace are not generated (they are not exposed in the global object)
        foreach (var binding in WebAssemblyBindings<TAdapter, TValue>.Interfaces)
        {
            byClrType.TryAdd(binding.ClrType, binding);
        }

        foreach (var binding in interfaces.Values)
        {
            if (binding.ParentName is { } parentName && interfaces.TryGetValue(parentName, out var parent))
            {
                binding.Parent = parent;
            }

            byClrType.TryAdd(binding.ClrType, binding);
        }

        s_byClrType = byClrType;
        return byClrType;
    }
}
